#include <iostream>
#include <string>
#include <sstream>
#include <iomanip>
#include <vector>
#include <unordered_map>
#include <cctype>

// Demonstrates Check Protection (Ex 8.33) and Text Token Analysis (Ex 8.31)
std::string protectCheck(double amount, int width = 9) {
    std::ostringstream oss;
    oss << std::fixed << std::setprecision(2) << amount;
    std::string valStr = oss.str();
    if (static_cast<int>(valStr.length()) < width) {
        valStr = std::string(width - valStr.length(), '*') + valStr;
    }
    return valStr;
}

int main() {
    double checkAmount = 99.87;
    std::cout << "Protected Check: " << protectCheck(checkAmount, 9) << "\n";

    std::string text = "To be, or not to be: that is the question:";
    std::unordered_map<char, int> letterCounts;
    std::vector<std::string> words;

    std::string currentWord;
    for (char ch : text) {
        if (std::isalpha(static_cast<unsigned char>(ch))) {
            letterCounts[static_cast<char>(std::tolower(ch))]++;
            currentWord += static_cast<char>(std::tolower(ch));
        } else if (!currentWord.empty()) {
            words.push_back(currentWord);
            currentWord.clear();
        }
    }
    if (!currentWord.empty()) {
        words.push_back(currentWord);
    }

    // 't' appears 7 times: To(1), not(1), to(1), that(2), the(1), question(1)
    std::cout << "Letter 't' count: " << letterCounts['t'] << "\n";
    // 'b' appears 2 times: be(1), be(1)
    std::cout << "Letter 'b' count: " << letterCounts['b'] << "\n";
    // Total words: To, be, or, not, to, be, that, is, the, question -> 10 words
    std::cout << "Total words: " << words.size() << "\n";
    return 0;
}
